-- 518: Original BrillaPrep NSMQ subj_nsmq_math round_one beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_518_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_518_guard;
INSERT INTO _migration_518_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_math_quadratic' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the discriminant of the quadratic equation 2x² − 3x + 5 = 0?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. −31","B. 49","C. −11","D. 31"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The discriminant is Δ = b² − 4ac with a = 2, b = −3, c = 5: Δ = (−3)² − 4(2)(5) = 9 − 40 = −31. Because Δ is negative, the equation has no real roots. Squaring −3 correctly gives +9; forgetting the sign change gives the wrong value 49.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_518_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_math_calculus' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the derivative of sin x with respect to x?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. −cos x","B. cos x","C. −sin x","D. tan x"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The standard derivative is d/dx(sin x) = cos x. The derivative of cos x is −sin x, which is the common confusion; tan x differentiates to sec²x, not sin x.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_518_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_math_trigonometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the exact value of sin 30°?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. √3/2","B. √2/2","C. 1/2","D. 1"]' AND q.correct_answer IS 'C' AND q.explanation IS 'From the standard 30-60-90 triangle, sin 30° = opposite/hypotenuse = 1/2. The value √3/2 is cos 30° (equivalently sin 60°), and √2/2 belongs to the 45° angle.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_518_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_math_statistics' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the median of the data set 3, 7, 9, 12, 15?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 7","B. 9.2","C. 12","D. 9"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The data are already in ascending order with five values, so the median is the middle (third) value, 9. The value 9.2 is the mean (46 ÷ 5), a common confusion between the two averages.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_r1_b002_001', 'topic_nsmq_math_quadratic', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'What is the discriminant of the quadratic equation 2x² − 3x + 5 = 0?', 'multiple_choice', 'round_one', '["A. −31","B. 49","C. −11","D. 31"]', 'A', 'The discriminant is Δ = b² − 4ac with a = 2, b = −3, c = 5: Δ = (−3)² − 4(2)(5) = 9 − 40 = −31. Because Δ is negative, the equation has no real roots. Squaring −3 correctly gives +9; forgetting the sign change gives the wrong value 49.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
