INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_r1_b002_003', 'topic_nsmq_math_trigonometry', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'What is the exact value of sin 30°?', 'multiple_choice', 'round_one', '["A. √3/2","B. √2/2","C. 1/2","D. 1"]', 'C', 'From the standard 30-60-90 triangle, sin 30° = opposite/hypotenuse = 1/2. The value √3/2 is cos 30° (equivalently sin 60°), and √2/2 belongs to the 45° angle.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_r1_b002_004', 'topic_nsmq_math_statistics', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'What is the median of the data set 3, 7, 9, 12, 15?', 'multiple_choice', 'round_one', '["A. 7","B. 9.2","C. 12","D. 9"]', 'D', 'The data are already in ascending order with five values, so the median is the middle (third) value, 9. The value 9.2 is the mean (46 ÷ 5), a common confusion between the two averages.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-002', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_math_r1_b002_001', 'q_nsmq_math_r1_b002_002', 'q_nsmq_math_r1_b002_003', 'q_nsmq_math_r1_b002_004');
